WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessionized AS (SELECT id, txn_time, merchant, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, COUNT(CASE WHEN merchant = 'Grab' THEN 1 END) AS grab_count, MAX(txn_time) AS ended_at, MAX(txn_time) AS ended_at_2, AVG(island_id) FILTER (WHERE merchant = 'Starbucks') AS starbucks_avg_island_id, ROUND(SUM(island_id) / NULLIF(COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END), 0), 2) AS island_id_per_amazon, SUM(island_id) FILTER (WHERE merchant = 'Amazon') AS amazon_total_island_id FROM sessionized GROUP BY year_start HAVING island_id_per_amazon >= 0;
